export const isDecayed = (world: World, entity: TypedEntity) =>
  entity[DROPPABLE]?.decayed || entity[VANISHABLE]?.decayed;

export const isDecaying = (world: World, entity: TypedEntity) =>
  isDead(world, entity) &&
  !isDecayed(world, entity) &&
  !getSequence(world, entity, "decay") &&
  !getSequence(world, entity, "vanish");

export const isHarvested = (world: World, entity: TypedEntity) =>
  hasComponent(entity, HARVESTABLE) &&
  entity[HARVESTABLE].amount <= 0 &&
  !isDecayed(world, entity) &&
  !getSequence(world, entity, "decay");

export const isDroppable = (world: World, position: Position) =>
  !!world.metadata.gameEntity[LEVEL].walkable[position.x][position.y] &&
  !getBurning(world, position);

export const animateEvaporate = (world: World, entity: TypedEntity<"POSITION">) => {
  // play evaporate animation with own anchor
  const evaporate =
    entity[DROPPABLE]?.evaporate || entity[VANISHABLE]?.evaporate;

  if (!evaporate) return;

  const castableEntity = entities.createSpell(world, {
    [BELONGABLE]: { faction: entity[BELONGABLE]?.faction || "nature" },
    [CASTABLE]: getEmptyCastable(world, entity),
    [ORIENTABLE]: {},
    [POSITION]: copy(entity[POSITION]),
    [RENDERABLE]: { generation: 0 },
    [SEQUENCABLE]: { states: {} },
    [SPRITE]: none,
  });
  createSequence<"evaporate", EvaporateSequence>(
    world,
    castableEntity,
    "evaporate",
    "creatureEvaporate",
    { fast: evaporate.fast, sprite: evaporate.sprite }
  );
};

export const placeRemains = (
  world: World,
  entity: TypedEntity,
  position = requireComponent(entity, POSITION)
) => {
  const remains = entity[REMAINABLE]?.cell;

  if (remains && !isImmersible(world, position)) {
    createCell(world, position, remains, "hidden");
  }
};

export const MAX_DROP_RADIUS = 5;
export const findAdjacentDroppable = (
  world: World,
  position: Position,
  maxRadius: number = MAX_DROP_RADIUS,
  overrideCenterWalkable?: boolean
) => {
  const level = world.metadata.gameEntity[LEVEL] as Level;

  // allow using dropEntity during world generation
  if (level.walkable.length === 0) return position;

  if (
    overrideCenterWalkable !== false &&
    (overrideCenterWalkable === true || isDroppable(world, position))
  ) {
    return position;
  }

  let drop: Position | undefined;
  iterateMatrixFromCenter(
    level.cells,
    position,
    (x, y) => {
      if (isDroppable(world, { x, y })) {
        drop = { x, y };
        return true;
      }
    },
    maxRadius,
    true
  );

  if (drop) return drop;

  console.error(
    Date.now(),
    "Unable to find free adjacent drop location at:",
    position
  );
  return position;
};

type InventoryItemData<T> = Omit<T, "ITEM" | "RENDERABLE"> &
  Pick<TypedEntity<"ITEM" | "RENDERABLE">, "ITEM" | "RENDERABLE">;

function createGroundDrop(
  world: World,
  position: Position,
  item: Pick<Item, "stackable" | "amount">,
  sprite: Sprite,
  items: number[] = [],
  disposable = true
) {
  const data = {
    [FOG]: { visibility: "fog", type: "unit" } as const,
    [HOOKABLE]: { escaping: false },
    [INVENTORY]: { items },
    [LAYER]: {},
    [LOOTABLE]: { disposable },
    [POSITION]: copy(position),
    [RENDERABLE]: { generation: 0 },
    [SEQUENCABLE]: { states: {} },
    [SPRITE]: sprite,
    [SWIMMABLE]: { swimming: false },
  };
  return item.stackable === "worm" && item.amount === 1
    ? entities.createMiniature(world, {
        ...data,
        [BEHAVIOUR]: { patterns: [{ name: "worm", memory: {} }] },
        [MOVABLE]: {
          orientations: [],
          reference: world.getEntityId(world.metadata.gameEntity),
          spring: {
            duration: 350,
          },
          lastInteraction: 0,
          flying: false,
          swimming: false,
        },
        [ORIENTABLE]: {},
      })
    : entities.createDrop(world, data);
}

export const createItemAsDrop = <T extends TypedEntity<"ITEM" | "RENDERABLE">>(
  world: World,
  position: Position,
  factory: (world: World, data: InventoryItemData<T>) => T,
  entity: Omit<T, "ITEM" | "RENDERABLE"> & {
    [ITEM]: Omit<Item, "carrier">;
  },
  drop = true
) => {
  const containerEntity = createGroundDrop(world, position, entity[ITEM], drop ? shadow : none);
  return createItemInInventory(world, containerEntity, factory, entity);
};

export const createItemInInventory = <
  T extends TypedEntity<"ITEM" | "RENDERABLE">
>(
  world: World,
  carrier: TypedEntity<"INVENTORY" | "POSITION">,
  factory: (world: World, data: InventoryItemData<T>) => T,
  entity: Omit<T, "ITEM" | "RENDERABLE"> & {
    [ITEM]: Omit<Item, "carrier" | "bound">;
  },
  equip: boolean = true
) => {
  const itemEntity = factory(world, {
    ...entity,
    [ITEM]: {
      bound: false,
      ...entity[ITEM],
      carrier: world.getEntityId(carrier),
    },
    [RENDERABLE]: { generation: 0 },
  });

  // add to inventory
  const itemId = world.getEntityId(itemEntity);
  const isEquipment = slots.some((slot) => itemEntity[ITEM][slot]);
  const targetConsume = itemEntity[ITEM].consume;
  const targetStackable = itemEntity[ITEM].stackable;

  if (!equip) {
    carrier[INVENTORY].items.push(itemId);
  } else if (isEquipment) {
    attemptEquipItem(world, carrier, itemEntity);
    carrier[INVENTORY].items.push(itemId);
  } else if (targetConsume || targetStackable) {
    carrier[INVENTORY].items.push(itemId);
  } else {
    carrier[INVENTORY].items.push(itemId);
  }
  return itemEntity;
};

function animateDrop(
  world: World, drop: TypedEntity, item: TypedEntity<"ITEM">, origin: Position, delay?: number
) {
  createSequence<"collect", CollectSequence>(world, drop, "collect", "itemCollect", {
    origin: copy(origin), itemId: world.getEntityId(item), drop: true, amount: item[ITEM].amount, delay,
  });
}

export function dropBagItem(
  world: World,
  carrier: TypedEntity<"INVENTORY" | "POSITION">,
  selected: TypedEntity<"ITEM" | "SPRITE">,
  destination?: Position,
  amount = 1
) {
  const item = { ...selected[ITEM], amount, bound: false };
  const position = destination || findAdjacentDroppable(world, carrier[POSITION], MAX_DROP_RADIUS, false);
  const drop = createGroundDrop(world, position, item, destination ? none : shadow, [], !destination);
  drop[LOOTABLE].droppedBy = world.getEntityId(carrier);
  let dropped = selected;
  if (selected[ITEM].amount === amount) {
    removeFromInventory(world, carrier, selected);
    selected[ITEM].bound = false;
    selected[ITEM].carrier = world.getEntityId(drop);
    drop[INVENTORY].items.push(world.getEntityId(selected));
  } else {
    selected[ITEM].amount -= amount;
    dropped = createItemInInventory(world, drop, entities.createItem, {
      [ITEM]: item,
      [SPRITE]: getItemSprite(item),
    });
    rerenderEntity(world, carrier);
  }
  if (destination) {
    drop[INVENTORY].items.length = 0;
    animateDrop(world, drop, dropped, carrier[POSITION]);
    registerEntity(world, drop);
  }
  return drop;
}

export const dropEntity = (
  world: World,
  entity: TypedEntity,
  position: Position,
  overrideCenterWalkable?: boolean,
  maxRadius: number = MAX_DROP_RADIUS,
  orientation?: Orientation,
  delay?: number
) => {
  const size = world.metadata.gameEntity[LEVEL].size;
  const inventory = entity[INVENTORY]?.items || [];

  placeRemains(world, entity, position);

  // convert wood sword back to stick
  const stickId = inventory.find((itemId: number) => {
    const itemEntity = world.assertByIdAndComponents(itemId, [ITEM]);
    return (
      !itemEntity[ITEM].bound &&
      itemEntity[ITEM].weapon === "sword" &&
      itemEntity[ITEM].material === "wood" &&
      !itemEntity[ITEM].element
    );
  });
  if (stickId) {
    const swordEntity = world.assertById(stickId);
    removeFromInventory(world, entity, swordEntity);

    disposeEntity(world, swordEntity);

    const stickEntity = entities.createItem(world, {
      [ITEM]: {
        amount: 1,
        stackable: "stick",
        carrier: -1,
        bound: false,
      },
      [RENDERABLE]: { generation: 0 },
      [SPRITE]: getItemSprite({ stackable: "stick" }),
    });
    requireComponent(entity, INVENTORY).items.push(world.getEntityId(stickEntity));
  }

  // remember if entity was holding a compass
  if (entity[EQUIPPABLE]?.compass && entity[SPAWNABLE]) {
    entity[SPAWNABLE].compassId = entity[EQUIPPABLE].compass;
  }

  const arrowHits = entity[SHOOTABLE]?.shots || 0;
  const recharge = entity[RECHARGABLE]?.hit;
  const items = [
    ...(inventory.filter(
      (itemId: number) =>
        !world.assertByIdAndComponents(itemId, [ITEM])[ITEM].bound
    ) || []),
    ...(arrowHits > 0
      ? [
          world.getEntityId(
            entities.createItem(world, {
              [ITEM]: {
                amount: arrowHits,
                stackable: "arrow",
                carrier: -1,
                bound: false,
              },
              [RENDERABLE]: { generation: 0 },
              [SPRITE]: arrow,
            })
          ),
        ]
      : []),
    ...(recharge
      ? [
          world.getEntityId(
            entities.createItem(world, {
              [ITEM]: {
                amount: 1,
                stackable: "charge",
                carrier: -1,
                bound: false,
              },
              [RENDERABLE]: { generation: 0 },
              [SPRITE]: charge,
            })
          ),
        ]
      : []),
  ];

  return shuffle(items).map((itemId, index) => {
    const dropPosition = orientation
      ? combine(size, position, orientationPoints[orientation])
      : findAdjacentDroppable(
          world,
          position,
          maxRadius,
          overrideCenterWalkable
            ? index === 0
              ? overrideCenterWalkable
              : undefined
            : overrideCenterWalkable
        );

    const isCentered =
      dropPosition.x === position.x &&
      dropPosition.y === position.y &&
      !(overrideCenterWalkable && delay);

    const itemEntity = world.assertByIdAndComponents(itemId, [ITEM]);
    const previousCarrier = itemEntity[ITEM].carrier;
    const carrierEntity = world.getEntityByIdAndComponents(previousCarrier, [
      POSITION,
    ]);

    // assign identifiers to all unnamed drops
    const identifier =
      carrierEntity?.[IDENTIFIABLE]?.name || entity[IDENTIFIABLE]?.name;
    if (identifier && !itemEntity[IDENTIFIABLE]?.name) {
      setIdentifier(world, itemEntity, `${identifier}:drop`);
    }

    const containerEntity = createGroundDrop(
      world, dropPosition, itemEntity[ITEM],
      !isCentered || (entity[POSITION] && isImmersible(world, entity[POSITION])) ? none : shadow,
      isCentered ? [itemId] : [], isCentered
    );

    if (itemEntity[POPUP]) {
      const { viewpoint, ...popup } = itemEntity[POPUP];
      createPopup(world, containerEntity, popup);
    }

    // reset orientable e.g. from using sword
    if (itemEntity[ORIENTABLE]?.facing) {
      itemEntity[ORIENTABLE].facing = undefined;
    }

    // animate drop if not on center position
    if (!isCentered) {
      animateDrop(world, containerEntity, itemEntity, carrierEntity?.[POSITION] || position, delay);
    }

    if (carrierEntity) {
      removeFromInventory(world, carrierEntity, itemEntity);
    }

    const containerId = world.getEntityId(containerEntity);
    itemEntity[ITEM].carrier = containerId;

    registerEntity(world, containerEntity);

    return containerEntity;
  });
};

function hatchEgg(world: World, drop: TypedEntity<"LOOTABLE" | "POSITION">) {
  const item = world.getEntityByIdAndComponents(drop[INVENTORY]?.items[0], [ITEM, SPRITE]);
  if (item?.[ITEM].stackable !== "egg" || !Number.isFinite(item[ITEM].amount)) return;

  const stage = drop[LOOTABLE].crack || 0;
  if (!stage && Math.random() >= 0.001) return;
  if (stage < 3) {
    drop[LOOTABLE].crack = stage + 1;
    item[SPRITE] = spriteRef(customSprite({
      name: egg.name,
      layers: getFacingLayers(eggCrack, undefined, stage + 1),
    }));
  } else {
    delete drop[LOOTABLE].crack;
    item[SPRITE] = spriteRef(egg);
    spendItem(world, drop, { ...item[ITEM], amount: 1 }, item);
    createCell(world, drop[POSITION], "chick", drop[FOG]?.visibility || "fog", false);
  }
  rerenderEntity(world, drop);
}

export default function setupDrop(world: World) {
  let worldGeneration = world.metadata.gameEntity[RENDERABLE]?.generation;
  let referencesGeneration = -1;

  const onUpdate = (delta: number) => {
    const generation = world
      .getEntities([RENDERABLE, REFERENCE])
      .reduce((total, entity) => entity[RENDERABLE].generation + total, 0);
    const heroEntity = world.getEntity([PLAYER]);

    if (referencesGeneration === generation) return;

    referencesGeneration = generation;

    // create decay animation
    for (const entity of world.getEntities([
      DROPPABLE,
      RENDERABLE,
      SEQUENCABLE,
      POSITION,
    ])) {
      if (entity[BURNABLE]?.burning || entity[BURNABLE]?.combusted) continue;
      if (isDecaying(world, entity)) {
        if (entity[TAMEABLE]?.owner !== undefined) {
          petKnockout(world, entity);
          continue;
        }
        if (heroEntity && entity[NPC] && getRoot(world, entity) === entity) rewardPetKill(world, heroEntity, entity);
        if (entity[TAMEABLE] && entity[INVENTORY]) {
          populateInventory(world, world.assertComponents(entity, [INVENTORY, POSITION]), [
            { stackable: "resource", material: "wood", element: "air", amount: 1 },
          ]);
        }
        play(world, entity, "die", {
          variant: entity[NPC] ? 1 : 2,
          intensity: entity[STATS]?.maxHp,
        });
        createSequence<"decay", DecaySequence>(
          world,
          entity,
          "decay",
          "creatureDecay",
          { fast: false }
        );
        dropEntity(
          world,
          entity,
          entity[POSITION],
          undefined,
          MAX_DROP_RADIUS,
          undefined,
          lootSpeed + decayTime / 2
        );
      }
    }

    // create vanish animation
    for (const entity of world.getEntities([
      POSITION,
      RENDERABLE,
      SEQUENCABLE,
      VANISHABLE,
    ])) {
      const rootEntity = getRoot(world, entity);

      if (isDecaying(world, entity)) {
        if (heroEntity && entity[NPC] && getRoot(world, entity) === entity) rewardPetKill(world, heroEntity, entity);
        play(world, entity, "die", {
          variant: entity[NPC] ? 1 : 2,
          intensity: entity[STATS]?.maxHp,
        });
        createSequence<"vanish", VanishSequence>(
          world,
          entity,
          "vanish",
          "creatureVanish",
          {
            generation: 0,
            grow: true,
            remaining: 0,
            type: entity[VANISHABLE].type,
          }
        );
      } else if (isDead(world, rootEntity) && isDecayed(world, entity)) {
        // dropping items is handled by vanish sequence
        disposeEntity(world, entity, true, false);

        const unitKey = entity[NPC]?.type;
        if (heroEntity && unitKey) {
          heroEntity[PLAYER].defeatedUnits[unitKey] =
            (heroEntity[PLAYER].defeatedUnits[unitKey] || 0) + 1;
          heroEntity[PLAYER].kills += 1;
        }

        // create spawns and remains for vanished units
        const size = world.metadata.gameEntity[LEVEL].size;

        entity[VANISHABLE].cells.forEach((cell) => {
          const cellEntity = createCell(
            world,
            combine(size, entity[POSITION], cell.delta),
            cell.cell,
            "hidden"
          ).cell;
          registerEntity(world, cellEntity);
        });
      }
    }

    // drop harvested resources
    for (const entity of world.getEntities([
      DROPPABLE,
      HARVESTABLE,
      RENDERABLE,
      SEQUENCABLE,
      POSITION,
    ])) {
      if (isHarvested(world, entity)) {
        const { yields, harvestable } = getHarvestConfig(
          entity[HARVESTABLE].resource
        );
        const isDigging = harvestTools[harvestable.resource] === "shovel";

        if (isDigging) {
          const limbs = getLimbs(world, entity);
          limbs.forEach((limb) => {
            disposeEntity(world, limb, undefined, false);
          });
          if (
            pavingResources.includes(harvestable.resource) ||
            trenchResources.includes(harvestable.resource)
          ) {
            const { x, y } = entity[POSITION];
            world.metadata.gameEntity[LEVEL].cells[x][y] = "air";
            updateShoreline(world, entity[POSITION]);
          }
        } else {
          play(world, entity, "harvest", { variant: 4 });
          const limbs = getLimbs(world, entity);
          limbs.forEach((limb) => {
            createSequence<"decay", DecaySequence>(
              world,
              limb,
              "decay",
              "creatureDecay",
              { fast: false }
            );
          });
        }

        if (yields.length > 0) {
          const placeholder: TypedEntity<
            "INVENTORY" | "POSITION" | "LOOTABLE"
          > = {
            [LOOTABLE]: { disposable: true },
            [INVENTORY]: { items: [] },
            [POSITION]: copy(entity[POSITION]),
            [RENDERABLE]: { generation: 0 },
          };
          populateInventory(world, placeholder, yields);
          dropEntity(
            world,
            placeholder,
            placeholder[POSITION],
            !isDigging,
            undefined,
            undefined,
            isDigging ? 0 : lootSpeed + decayTime
          );
        }

        dropEntity(
          world,
          entity,
          entity[POSITION],
          yields.length === 0 && !isDigging,
          undefined,
          undefined,
          isDigging ? 0 : lootSpeed + decayTime / (yields.length === 0 ? 1 : 2)
        );
      } else if (
        isDecayed(world, entity) &&
        !entity[BURNABLE]?.combusted &&
        !isDead(world, entity)
      ) {
        disposeEntity(world, entity, true);
      }
    }

    // decay harvested limbs
    for (const entity of world.getEntities([
      FRAGMENT,
      RENDERABLE,
      SEQUENCABLE,
      POSITION,
    ])) {
      if (hasComponent(entity, STRUCTURABLE)) continue;

      const rootEntity = getStructure(world, entity);

      if (rootEntity && !hasComponent(rootEntity, HARVESTABLE)) continue;

      if (!rootEntity || isDecayed(world, entity)) {
        disposeEntity(world, entity);
      }
    }

    // replace decayed entities, increase slay counter and evaporate unit
    for (const entity of world.getEntities([DROPPABLE, RENDERABLE, POSITION])) {
      if (!isDecayed(world, entity) || entity[BURNABLE]?.combusted) continue;
      const rootEntity = getRoot(world, entity);

      if (isDead(world, entity) || isDead(world, rootEntity)) {
        disposeEntity(world, entity, true, false);
        animateEvaporate(world, entity);

        const unitKey = entity[NPC]?.type;
        if (heroEntity && unitKey && entity === rootEntity) {
          heroEntity[PLAYER].defeatedUnits[unitKey] =
            (heroEntity[PLAYER].defeatedUnits[unitKey] || 0) + 1;
          heroEntity[PLAYER].kills += 1;
          if (unitKey === "tutorialBoss") checkUnlocks(world);
        }
      }
    }

    const tick = world.metadata.gameEntity[RENDERABLE].generation;
    const worldTick = worldGeneration !== undefined && tick !== worldGeneration;
    worldGeneration = tick;

    // Loose eggs hatch on world ticks. Empty drops use the normal loot cleanup.
    for (const entity of world.getEntities([LOOTABLE, RENDERABLE])) {
      if (!entity[LOOTABLE].disposable) continue;
      if (worldTick && entity[HOOKABLE] && hasComponent(entity, POSITION)) {
        hatchEgg(world, entity);
      }
      if (
        isEmpty(world, entity) &&
        !getSequence(world, entity, "dispose")
      ) {
        createSequence<"dispose", DisposeSequence>(
          world,
          entity,
          "dispose",
          "entityDispose",
          {}
        );
      }
    }
  };

  return { onUpdate };
}
