const chatHaste = -1001;
const popupHaste = -1002;
export const boatHaste = 12;

export const getHasteInterval = (world: World, haste: number) =>
  haste === chatHaste
    ? 10
    : haste === popupHaste
    ? 175
    : Math.floor(1350 / (Math.max(haste, -5) + 6) + 125);

export const setMovementOrientations = (
  world: World,
  entity: TypedEntity,
  orientations: Orientation[]
) => {
  // Dash keeps the movement component on the spell until recovery finishes.
  const movable: Movable | undefined =
    entity[MOVABLE] ??
    getActiveSpell(world, entity, "castDash")?.args.memory?.movable;
  if (!movable) return;
  const reference = world.assertByIdAndComponents(movable.reference, [
    REFERENCE,
  ])[REFERENCE];

  // A new dialog press steps immediately, then uses the normal repeat clock.
  if (
    orientations.length &&
    !movable.orientations.length &&
    isInPopup(world, entity)
  ) {
    reference.delta = reference.tick;
  }
  movable.orientations = orientations;
  if (!entity[MOVABLE]) movable.pendingOrientation = undefined;
  else if (orientations[0]) movable.pendingOrientation = orientations[0];

  if (orientations.length === 0 && !movable.momentum) {
    reference.suspensionCounter = 0;
    // Keep late direction taps and queued actions for the next tick.
    if (
      (reference.tick - reference.delta < 50 && movable.pendingOrientation) ||
      entity[ACTIONABLE]?.spellTriggered ||
      entity[ACTIONABLE]?.skillTriggered ||
      entity[ACTIONABLE]?.interactTriggered ||
      entity[PLAYER]?.actionTriggered
    ) {
      reference.suspensionCounter += 1;
    }
  } else {
    reference.suspensionCounter = -1;
    reference.suspended = false;
  }
};

export const getTempo = (world: World, position: Position) =>
  sum(
    getCellEntities(world, position).map((target) => target[TEMPO]?.amount || 0)
  );

export const getEntityHaste = (world: World, entity: TypedEntity) =>
  isInTab(world, entity, "chat")
    ? chatHaste
    : isInPopup(world, entity)
    ? popupHaste
    : isMounting(world, entity)
    ? boatHaste
    : getEntityStats(world, entity).haste;

export const updateMovementInterval = (world: World, entity: TypedEntity) => {
  const reference = world.assertByIdAndComponents(requireComponent(entity, MOVABLE).reference, [
    REFERENCE,
  ])[REFERENCE];
  const interval = getHasteInterval(world, getEntityHaste(world, entity));
  if (reference.tick === interval) return;
  reference.delta = Math.min(reference.delta / reference.tick, 1) * interval;
  reference.tick = interval;
};

export const getCollidable = (world: World, position: Position) =>
  getCellEntities(world, position).find(
    (entity) => COLLIDABLE in (entity as TypedEntity)
  );

export const isCollision = (world: World, position: Position) =>
  !!getCollidable(world, position);

export const isPassable = (
  world: World,
  position: Position,
  exclude?: TypedEntity,
  ignoreSnow = false
) => {
  if (
    !getOverlappingCell(
      world.metadata.gameEntity[LEVEL].initialized,
      position.x,
      position.y
    )
  )
    return false;

  const lockable = getLockable(world, position);
  const collidable = getCollidable(world, position);
  const attackable = getAttackable(world, position);

  return (
    (!collidable || collidable === exclude) &&
    (!attackable || attackable === exclude) &&
    !(lockable && isLocked(world, lockable)) &&
    !getLootable(world, position) &&
    !getCollecting(world, position) &&
    !getClickable(world, position, ignoreSnow)
  );
};

export const isFloatable = (
  world: World,
  position: Position,
  exclude?: TypedEntity
) => isPassable(world, position, exclude) && isImmersible(world, position);

export const isWalkable = (
  world: World,
  position: Position,
  exclude?: TypedEntity
) => isPassable(world, position, exclude) && !isSubmerged(world, position);

// Planning can cross snow; the click system still spends a turn clearing it.
export const isPathable = (world: World, position: Position) =>
  isPassable(world, position, undefined, true) && !isSubmerged(world, position);

export const isRoamable = (
  world: World,
  entity: TypedEntity,
  position: Position
) => {
  // avoid fires
  const castableEntity = getExertables(world, position).map((exertable) =>
    world.getEntityByIdAndComponents(exertable[EXERTABLE].castable, [CASTABLE])
  )[0];
  const isFire = castableEntity && castableEntity[CASTABLE].burn > 0;
  if (isFire) return false;

  // don't walk through open locks
  const isLockable = getLockable(world, position);
  if (isLockable) return false;

  if (!isMovable(world, entity, position)) return false;

  return true;
};

// A companion can catch a departing boat and swim back to shore if the owner lands first.
export const canSwimToBoat = (world: World, pet: TypedEntity) => {
  const owner = world.getEntityById(pet[TAMEABLE]?.owner);
  return !!owner && (world.getEntityById(owner[PLAYER]?.mount)?.[MOUNTABLE]?.medium === "water" ||
    (!!pet[POSITION] && isSubmerged(world, pet[POSITION])));
};

export const isLimbWalkable = (
  world: World,
  entity: TypedEntity,
  position: Position
) => {
  if (entity[FRAGMENT]?.structure) {
    const fragmentEntity = getFragment(world, position);

    if (
      fragmentEntity &&
      entity[FRAGMENT].structure === fragmentEntity[FRAGMENT]?.structure
    )
      return true;
  }

  const pet = entity[PLAYER] && getAttackable(world, position);
  return isWalkable(world, position, pet && pet[TAMEABLE]?.owner === world.getEntityId(entity) ? pet : undefined) ||
    (!!entity[TAMEABLE]?.owner && isFloatable(world, position) && canSwimToBoat(world, entity));
};

export const isFlyable = (world: World, position: Position) => {
  const lockable = getLockable(world, position);
  return (
    !getOpaque(world, position) && !(lockable && isLocked(world, lockable))
  );
};

export const isMovable = (world: World, entity: TypedEntity, position: Position) => {
  if (!entity[MOVABLE]) return false;

  if (isLimbWalkable(world, entity, position)) return true;

  const spikable = getSpikable(world, position);
  if (spikable && isNeutral(world, spikable)) return false;

  // allow attacking opposing entities
  const attackable = getAttackable(world, position);
  if (
    getRoot(world, entity)[EQUIPPABLE]?.weapon &&
    attackable &&
    !isFriendlyFire(world, entity, attackable)
  )
    return true;

  // allow clicking
  const clickable = getClickable(world, position);
  if (clickable && (!requireComponent(clickable, CLICKABLE).player || entity[PLAYER]))
    return true;

  return false;
};

export const getBiome = (world: World, position: Position): BiomeName => {
  const biomes = world.metadata.gameEntity[LEVEL].biomes;
  if (biomes.length === 0) return "jungle";

  return getOverlappingCell(
    world.metadata.gameEntity[LEVEL].biomes,
    position.x,
    position.y
  );
};

export default function setupMovement(world: World) {
  let referenceGenerations = -1;
  const entityReferences: Record<string, number> = {};
  const nextSail: Record<string, number> = {};

  const onUpdate = (delta: number) => {
    const size = world.metadata.gameEntity[LEVEL].size;

    const generation = world
      .getEntities([RENDERABLE, REFERENCE])
      .reduce((total, entity) => entity[RENDERABLE].generation + total, 0);

    if (referenceGenerations === generation) return;

    referenceGenerations = generation;

    // let displacable units and mobs take precendence over player movements
    const orderedEntities: TypedEntity<"POSITION" | "MOVABLE" | "RENDERABLE">[] = [];
    const waitingPets: typeof orderedEntities = [];
    for (const entity of world.getEntities([POSITION, MOVABLE, RENDERABLE])) {
      if (entity[PLAYER]) continue;
      if (entity[TAMEABLE]?.owner && !entity[MOVABLE].orientations.length && !entity[MOVABLE].momentum) {
        waitingPets.push(entity);
      } else orderedEntities.push(entity);
    }
    // An idle companion can take the square its owner just vacated on this tick.
    orderedEntities.push(...world.getEntities([POSITION, MOVABLE, RENDERABLE, PLAYER]), ...waitingPets);

    for (const entity of orderedEntities) {
      const entityId = world.getEntityId(entity);
      const movableReference = world.assertByIdAndComponents(
        entity[MOVABLE].reference,
        [REFERENCE, RENDERABLE]
      );
      const entityReference = movableReference[RENDERABLE].generation;

      // skip if reference frame is unchanged
      if (entityReferences[entityId] === entityReference) continue;

      entityReferences[entityId] = entityReference;

      const pushSound = entity[DISPLACABLE]?.pushSound;
      delete entity[DISPLACABLE]?.pushSound;
      const pendingOrientation = entity[MOVABLE].pendingOrientation;
      entity[MOVABLE].pendingOrientation = undefined;

      // skip if immovable or not sliding
      if (
        (isDead(world, entity) && !entity[TAMEABLE]?.ghost) ||
        (hasComponent(entity, FRAGMENT) && isDead(world, getRoot(world, entity))) ||
        (isFrozen(world, entity) && !entity[MOVABLE].momentum)
      )
        continue;

      const attemptedOrientations: Orientation[] = [
        ...entity[MOVABLE].orientations,
      ];

      if (
        pendingOrientation &&
        !attemptedOrientations.includes(pendingOrientation)
      ) {
        attemptedOrientations.push(pendingOrientation);
      }

      if (entity[MOVABLE].momentum) {
        attemptedOrientations.unshift(entity[MOVABLE].momentum);
      }

      // skip if no attempted movement
      if (attemptedOrientations.length === 0) continue;

      // set facing regardless of movement
      const rigid = entity[STRUCTURABLE]?.rigid;
      if (entity[ORIENTABLE] && !entity[MOVABLE].flying && !rigid)
        entity[ORIENTABLE].facing = attemptedOrientations[0];

      // skip if already interacted
      if (
        entity[MOVABLE].lastInteraction === entityReference &&
        !entity[MOVABLE].momentum
      )
        continue;

      // move whole rigid body
      const limbs = rigid ? getLimbs(world, entity) : [entity];
      let movedOrientation: Orientation | undefined;

      for (const orientation of attemptedOrientations) {
        const delta = orientationPoints[orientation];
        let obstructed = false;

        for (const limb of limbs) {
          const limbPosition = requireComponent(limb, POSITION);
          const position = combine(size, limbPosition, delta);
          const movement = requireComponent(limb, MOVABLE);
          if (
            (!movement.swimming &&
              isLimbWalkable(world, limb, position)) ||
            (movement.flying && isFlyable(world, position)) ||
            (movement.swimming &&
              isFloatable(world, position) &&
              isImmersible(world, limbPosition))
          ) {
            continue;
          }
          // A thaw can strand a walker in deep water. Only allow a step towards shore.
          if (
            !movement.flying && !movement.swimming &&
            isImmersible(world, limbPosition) && isPassable(world, position) &&
            isSubmerged(world, limbPosition) &&
            orientations.every((side) =>
              isSubmerged(world, combine(size, requireComponent(limb, POSITION), orientationPoints[side]))
            )
          ) {
            const limbPosition = requireComponent(limb, POSITION);
            const shore = iterateMatrixFromCenter(
              world.metadata.gameEntity[LEVEL].cells,
              limbPosition,
              (x, y) => !isSubmerged(world, { x, y })
            );
            if (shore && relativeOrientations(world, limbPosition, shore, 1)[0] === orientation)
              continue;
          }
          obstructed = true;
          break;
        }

        if (!obstructed) {
          movedOrientation = orientation;
          break;
        }
      }

      if (movedOrientation) {
        if (pushSound) play(world, entity, "push");
        const delta = orientationPoints[movedOrientation];
        const rootPosition = combine(size, entity[POSITION], delta);
        const boat = entity[MOUNTABLE]?.medium === "water";
        if (
          boat &&
          entityReference >= (nextSail[entityId] ?? 0) &&
          isImmersible(world, entity[POSITION])
        ) {
          play(world, entity, "sail");
          nextSail[entityId] = entityReference + 5;
        }

        if (entity[PLAYER]) {
          const destination = getCellEntities(world, rootPosition);
          const pet = destination.find(other => other[TAMEABLE]?.owner === entityId);
          if (pet?.[MOVABLE]) pet[MOVABLE].pendingOrientation = invertOrientation(movedOrientation);
          const variant = isImmersible(world, rootPosition)
            ? 3
            : getTempo(world, rootPosition) < 0
            ? 2
            : 1;
          play(world, entity, "move", {
            intensity: movableReference[REFERENCE].tick,
            variant,
            volume: destination.some(
              (cell) =>
                cell[RENDERABLE] && resolveSprite(cell[SPRITE])?.layers.length
            )
              ? 1
              : 0.5,
          });
        } else if (
          entity[MOVABLE].flying &&
          entity[BEHAVIOUR]?.patterns.some((pattern) => pattern.name === "tumbleweed")
        ) {
          play(world, entity, "tumbleweed");
        } else if (entity[NPC] && entity[FOG]?.visibility === "visible") {
          play(world, entity, "slide", {
            intensity: movableReference[REFERENCE].tick,
            variant: npcVariants[entity[NPC].type],
          });
        }

        const passenger = world.getEntityByIdAndComponents(
          entity[MOUNTABLE]?.passenger,
          [MOVABLE]
        );
        const parts = [...limbs, ...(passenger ? [passenger] : [])];

        for (const part of parts) {
          // leave bubble trail if walking through water
          const position = requireComponent(part, POSITION);
          if (isImmersible(world, position) && !requireComponent(part, MOVABLE).flying) {
            createBubble(world, requireComponent(part, POSITION), "water", !boat);
          }

          // set facing to actual movement
          if (!rigid && part[ORIENTABLE] && !requireComponent(part, MOVABLE).flying) {
            part[ORIENTABLE].facing = movedOrientation;
          }

          const limbPosition = combine(size, position, delta);
          moveEntity(world, part, limbPosition);
          rerenderEntity(world, part);
        }
      } else {
        if (
          entity[MOVABLE].swimming &&
          !isImmersible(world, entity[POSITION])
        ) {
          // bump stranded entities
          if (!hasComponent(entity, BUMPABLE)) {
            world.addComponentToEntity(entity, BUMPABLE, {
              generation: 0,
            });
          }

          if (entity[BUMPABLE]) {
            bumpEntity(world, entity, "up");
            rerenderEntity(world, entity);
          }
        }
        if (entity[MOUNTABLE]) {
          // reset movement for vessels
          stopVessel(world, entity);
        }
      }

      // preserve momentum before suspending frame
      freezeMomentum(world, entity, movedOrientation);

      // mark as interacted but keep pending movement
      entity[MOVABLE].lastInteraction = entityReference;
    }
  };

  return { onUpdate };
}
